INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('6464840f-6be1-4ac2-8a90-14f9afccb4cf', 'Standing Shoulder Internal Rotatio (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Resistance Band Standing Shoulder Internal Rotatio, a comprehensive movement exercise. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Full body exercises are time-efficient and build functional, real-world strength.', '83601201', '83601201-Resistance-Band-Standing-Shoulder-Internal-Rotatio.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Secure the resistance band appropriately for Resistance Band Standing Shoulder Internal Rotatio. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Shoulder Internal Rotatio', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('646c9f01-55ab-4f97-bd50-4fe46d1f522f', 'Single Arm Low Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. The front delts assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. A well-developed chest contributes to upper body strength and aesthetics.', '86091201', '86091201-Cable-Single-Arm-Low-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'chest_fly', 'Single Arm Low Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('646e1316-1459-48c0-8a66-8cabce646835', 'Side Plank Glute Raise', 'Core', 'Bodyweight', '{"Glutes"}'::text[], '{"Abs","Shoulders"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '65331201', '65331201-Side-Plank-Glute-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Glute Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('64726a15-5625-44c4-919a-b9534a56c9dc', 'Single Leg Squat (TRX)', 'Legs', 'TRX', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Suspender Single Leg Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. Strong legs are the foundation for athletic performance and functional fitness.', '58311201', '58311201-Suspender-Single-Leg-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Single Leg Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pistol_squat', 'Suspender Single Leg Squat', 'squat, bench_press, deadlift', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('647d85a3-9d5d-4b7f-99d6-e6a7d0c266a3', 'Open Pulsing Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This bridging exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '73431201', '73431201-Open-Pulsing-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity. Perfect for targeting your glutes.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Open Pulsing Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('647f632c-0b27-4db5-ab3f-89f6b34863ea', 'Superman', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build a stronger core with the Superman, focusing on your abs. Your glutes work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '8041201', '08041201-Superman-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Set up in the starting position for Superman. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Superman', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64859d2a-a906-4d23-8acc-b087ab56c502', 'Step Up Crossover (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Secondary activation of your front delts provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '7991201', '07991201-Step-up-Crossover-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'chest_fly', 'Step Up Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64a81c0a-cc0b-47a7-89c6-dc1039ee5011', 'Standing Top To Forward Punches', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'Target your chest with the Standing Top To Forward Punches, an effective movement movement for upper body strength. You''ll also feel your shoulders working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '78191201', '78191201-Standing-Top-to-Forward-Punches-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Top To Forward Punches. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Top To Forward Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64baecd4-e214-45b7-8956-71d930684369', 'Seated Table Top Lat Stretch (Chair)', 'Back', 'Chair', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Designed to lengthen your lats, the Seated Table Top Lat Stretch On A Chair helps improve mobility and prevent stiffness. Your shoulders work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '104641201', '104641201-Seated-Table-Top-Lat-Stretch-on-a-Chair-(male)_St.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Table Top Lat Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'lat_stretch', 'Seated Table Top Lat Stretch On A Chair', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('64c3ee53-7bf5-4f83-92ba-ed0c52fdbdb5', 'Chair Squat To Toe Stand (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Leg training boosts metabolism and builds functional, real-world strength.', '87561201', '87561201-Chair-Squat-to-Toe-Stand-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'squat', 'Chair Squat To Toe Stand', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64c3f6de-eb9c-4a73-979b-e2c7a8c850d3', 'Standing Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger triceps with this kicking exercise for bigger arms. You''ll also feel your hamstrings working to support the movement. Performing this standing challenges your balance and core engagement. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '25981201', '25981201-Dumbbell-Standing-Kickback-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Kickback. 2. Stand tall with your feet firmly planted. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Standing Kickback', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('64d43181-7b3f-493a-afee-48df9a2e6737', 'Kneeling External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build leg strength with this rotation movement focusing on your rotator cuff. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '90761201', '90761201-Kneeling-External-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Kneeling External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64d49094-3292-41cd-9a51-e06fd2775b88', 'Narrow Squat', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Bodyweight Narrow Squat is a rowing exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '66531201', '66531201-Bodyweight-Narrow-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Narrow Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64df45fe-4a07-49f3-a1a7-a082bff58d33', 'Corn Cob - Side To Side Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '69561201', '69561201-Corn-Cob-(Side-to-Side)-Pull-up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Corn Cob Pull Up', 'Corn Cob Pull Up', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('64e1efd7-fbbd-4284-be8b-966a6deac268', 'Seated Cross Leg Stretch Hold', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '77881201', '77881201-Seated-Cross-Leg-Stretch-Hold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Cross Leg Stretch Hold. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 37, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Cross Leg Stretch Hold', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('64eee7b9-f167-407d-a698-bbecb47cf10a', 'Single Leg Stride Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic jumping movement gets your heart rate up while developing explosive strength. Your quads, calves work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '15921201', '15921201-Single-Leg-Stride-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Stride Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Stride Jump', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('64f4f3c2-282a-4044-8e9c-128b41137dc1', 'Lying Scissor Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Scissor Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '6211201', '06211201-Lying-Scissor-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Scissor Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Scissor Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('64fe19a9-d7f4-4e76-a455-62226df8f9ed', 'Stepback With Push', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic pushing movement gets your heart rate up while developing explosive strength. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '66451201', '66451201-Stepback-with-Push-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback With Push. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback With Push', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('650cd6ec-3b43-47bc-a25e-0e0e9947b321', 'Elbow Fly And Palm Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Elbow Fly And Palm Press, an effective pressing movement for upper body strength. You''ll also feel your front delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '55731201', '55731201-Elbow-Fly-and-Palm-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Great for building strength in your chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'chest_fly', 'Elbow Fly And Palm Press', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('650cfd69-811e-46ee-aca1-3ab5edb1a731', 'Bicep Curl (Machine)', 'Arms', 'Machine', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Arm strength supports grip, pulling, and pushing in compound movements.', '5751201', '05751201-Lever-Bicep-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lever Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('651862a1-c657-4e4f-bf77-498f4b6388e7', 'Inverted Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Inverted Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '4991201', '04991201-Inverted-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('651f2429-687b-44df-9577-d7b081074cd2', 'Seated Row (Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '22461201', '22461201-Lever-Seated-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Seated Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('653a15e7-8440-4f52-94b1-3e72bee3ac12', 'Predator Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Predator Jack builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '75281201', '75281201-Predator-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Set up in the starting position for Predator Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Predator Jack', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('653cb9ad-f351-4da9-b9d8-ff467a02d1dc', 'Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Suspender Plank, focusing on your abs. You''ll also feel your shoulders, lower back working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. Core strength is foundational for athletic performance and injury prevention.', '95011201', '95011201-Suspender-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('65597f50-cb55-442e-9afc-db4a5a4e1545', 'Bench Press - Close Grip (EZ Bar)', 'Chest', 'EZ Bar, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing movement isolates your triceps for improved arm development. You''ll also feel your chest working to support the movement. Arm strength supports grip, pulling, and pushing in compound movements.', '24321201', '24321201-EZ-bar-Close-Grip-Bench-Press_Upper-Arms-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'close_grip_bench', 'EZ Bar Bench Press - Close Grip', 'EZ Bar Bench Press - Close Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('656542a1-6fd9-4eaa-b05e-baf4d5f792b6', 'Supported Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '66001201', '66001201-Bodyweight-Supported-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. Ideal for quads strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Supported Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6572a13d-6a12-4142-a1e1-065ef1797d92', 'Pulldown - Close Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements. Aim for full range of motion on every rep.', '9741201', '09741201-Band-Close-Grip-Pulldown_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Secure the resistance band appropriately for Band Close Grip Pulldown. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Pulldown - Close Grip', 'Pulldown - Close Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('6574c4cc-2afa-46d8-be06-0e1b98385482', 'Step Up Knee Raise On Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '92791201', '92791201-Bodyweight-Step-up-Knee-Raise-on-Stepbox-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Bodyweight Step Up Knee Raise On Stepbox. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_raise', 'Step Up Knee Raise On Stepbox', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6579b1f1-b789-489c-aeca-8964874e7adb', 'Plyo Side Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '46751201', '46751201-Plyo-Side-Lunge-Stretch-(male)_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 60, 9, 8, TRUE, TRUE, 'hip_stretch', 'Plyo Side Lunge Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('657a4995-5431-41f8-abc6-ea9beeb28191', 'Bench Press - Close Grip (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing movement isolates your triceps for improved arm development. Secondary activation of your chest provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '23911201', '23911201-Barbell-Close-Grip-Bench-Press-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', 'Bench Press (Close Grip)', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Lying', NULL, 'Overhand (Pronated)', 'Narrow', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'close_grip_bench', 'Bench Press - Close Grip', 'Bench Press - Close Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('657fb4f5-b18c-4e7e-829e-1407eed38bd5', 'Seated Twist Stretch', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Obliques"}'::text[], 'The Seated Twist Stretch provides a deep stretch for your spine, ideal for recovery and mobility work. The obliques, lower back assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '79771201', '79771201-Seated-Twist-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Twist Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'russian_twist', 'Seated Twist Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('6581ad29-bd6f-49df-beeb-0083da67cfe2', 'Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '321201', '00321201-Barbell-Deadlift_Hips-FIX.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Grip a barbell with hands at the appropriate width for Barbell Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', 'Hip Hinge', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('659d08a0-64e0-403f-a9df-f4858c5d0948', 'Glute Bridge Skull Crusher (Dumbbell)', 'Legs', 'Dumbbells, Flat Bench', '{"Glutes","Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this bridging exercise for bigger arms. Your hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '74701201', '74701201-Dumbbell-Glute-Bridge-Skull-Crusher-(male)_Upper-A.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Glute Bridge Skull Crusher. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'tricep_extension', 'Glute Bridge Skull Crusher', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('65a29d5a-6be3-4e68-8f79-46d195505dc0', 'Low Chest Press (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '94371201', '94371201-Cable-Low-Chest-Press-(VERSION-2)-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'bench_press', 'Low Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('65a48d2d-a04f-4dcf-ba9d-e05ed549366c', 'Suspension Back Stretch (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Use this stretch to open up your back area and enhance overall flexibility. Cable resistance creates smooth, continuous muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '18001201', '18001201-Cable-Suspension-Back-Stretch_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Suspension Back Stretch. 2. Move into the stretch position for Cable Suspension Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, FALSE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Suspension Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'cable', TRUE, 1, 30, 2, 85, 88, 30, 92),
('65a715bd-ed98-432b-8164-7f094bf8fda5', 'Standing Adductor Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Standing Adductor Stretch is a lower body stretching exercise that targets your adductors. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '73151201', '73151201-Standing-Adductor-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Adductor Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'hip_adduction', 'Standing Adductor Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('65af08ff-dfee-4440-9f4b-190c8a79093c', 'Muscle Up (On Vertical Bar)', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Chest","Triceps"}'::text[], 'Build lat width and pulling strength with this movement movement. The chest, triceps assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '106981201', '106981201-Muscle-up-(on-vertical-bar)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Set up in the starting position for Muscle Up. 2. Execute the movement with proper form, focusing on your lats. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'general_exercise', 'Muscle Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('65cf1f5e-10e7-4050-9f83-7316a6804d38', 'Seated Windshield Wipers', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Windshield Wipers, focusing on your abs. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '54891201', '54891201-Sitting-Windshield-Wipers-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Windshield Wipers. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Windshield Wipers', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('65f0d28f-2131-411a-9801-5b6f9bcb8dcc', 'Standing Boat Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build a stronger core with the Standing Boat Row, focusing on your abs. Secondary activation of your biceps, rear delts provides additional muscle engagement. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '77571201', '77571201-Standing-Boat-Row-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Standing Boat Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6602c879-e358-422f-bc8e-5394fc0d196f', 'Inverted Back Row - Underhand Grip', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Underhand Grip Inverted Back Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '12231201', '12231201-Underhand-Grip-Inverted-Back-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Use an underhand (supinated) grip with palms facing up/toward you. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_exercise', 'Underhand Grip Inverted Back Row', 'Inverted Back Row - Underhand Grip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6618cf16-7f32-4a22-a8dd-3dbfd13dcde9', 'Calf Press Seated (Resistance Band)', 'Legs', 'Resistance Band, Chair', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted pressing exercise. The seated position helps isolate the target muscles by removing momentum. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '54091201', '54091201-Resistance-Band-Calf-Press-Sitting-on-Chair_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Calf Press Seated On Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Execute the pressing motion for Resistance Band Calf Press Seated On Chair, extending through the target muscles. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Press Seated On Chair', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('6619575d-0150-464c-a997-8d6b1d43909a', 'Weighted Chains Bench Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Barbell Weighted Chains Bench Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '15091201', '15091201-Barbell-Weighted-Chains-Bench-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Weighted Chains Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('66261eac-a5bb-4482-8cd3-118db4003074', 'Lying Hip Internal Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'This stretch specifically works on your hips, promoting flexibility and reducing muscle tightness. The glutes assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '89771201', '89771201-Lying-Hip-Internal-Rotation-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Lie down in the appropriate position for Lying Hip Internal Rotation. 2. Rotate your torso through the movement pattern for Lying Hip Internal Rotation. 3. Control the rotation in both directions—avoid using momentum. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Lying Hip Internal Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6630527b-bb43-418d-b27e-a694445e0806', 'Plank To Pike', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Plank To Pike is a core stabilization exercise that primarily targets your abs. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '81091201', '81091201-Plank-to-Pike-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank To Pike', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('663239a5-7628-4def-8335-79a47bedcfd5', 'Turn Knee Drive', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Maintain proper breathing - exhale during the effort phase.', '78161201', '78161201-Turn-Knee-Drive-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up in the starting position for Turn Knee Drive. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Turn Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6639845f-9c94-48e0-9535-f64faa754765', 'Arm Crossover', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Arm Crossover is a movement exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '46641201', '46641201-Arm-Crossover-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Arm Crossover. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('663ef882-72b0-49e8-b0b7-ccc371a7750e', 'Russian Twist Plus', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '72571201', '72571201-Russian-Twist-Plus-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Rotate your torso through the movement pattern for Russian Twist Plus. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist Plus', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('66445605-21bb-4197-a04e-873f2d8a8dd8', 'Teaser Pilates Stretching', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'This stretch specifically works on your lats, promoting flexibility and reducing muscle tightness. The shoulders assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '88251201', '88251201-Teaser-Pilates-(female)-Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Move into the stretch position for Teaser Pilates Stretching. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Teaser Pilates Stretching', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('664ca7a2-f239-42ee-8265-fbc7e117a6b0', 'Pulsing Triceps Kickback', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'The Bodyweight Pulsing Triceps Kickback is an arm kicking exercise targeting your glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '63771201', '63771201-Bodyweight-Pulsing-Triceps-Kickback-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Keep your upper arm stationary and extend your forearm back. 2. Squeeze at full extension, then return with control. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Pulsing Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('665769f4-6721-4671-aadf-957205d23dd4', 'Open Up Crab Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '87851201', '87851201-Open-Up-Crab-Walk-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Set up in the starting position for Open Up Crab Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Open Up Crab Walk', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('665945cb-3b51-44a7-ab35-479e755c6f2a', 'Elevated Mountain Climber (Chair)', 'Core', 'Step Platform, Chair', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'This climbing exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors, shoulders provides additional muscle engagement. Core strength is foundational for athletic performance and injury prevention.', '84201201', '84201201-Elevated-Mountain-Climber-with-Hands-on-a-Chair-(m.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. From plank position, drive one knee toward your chest. 3. Quickly switch legs, bringing the other knee forward. 4. Continue alternating at a quick pace while maintaining plank form. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'mountain_climber', 'Elevated Mountain Climber With Hands On A Chair', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('665a667a-bec2-4124-aa53-9105f255fa30', 'High Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the High Lunge helps improve mobility and prevent stiffness. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '58911201', '58911201-High-Lunge-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for High Lunge. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity. Ideal for quads strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'High Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('665ea892-146c-4d75-8b9d-babf77b84861', 'Seated Squat (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '12321201', '12321201-Lever-Seated-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Squat. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 95, 7, 9, TRUE, FALSE, 'squat', 'Lever Seated Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('66615945-83a7-40cc-be7e-362b0f47def3', 'Wide Chin Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. Secondary activation of your biceps provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '49151201', '49151201-Wide-Chin-Up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Pull yourself up, focusing on bicep and lat engagement. 2. Raise until chin is over the bar, lower with full control. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Wide Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66636e60-4ce1-449a-b9d0-a8fffaee62c3', 'Step Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning. Start with lighter weight to master the movement pattern.', '44181201', '44181201-Step-Jack-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Step Jack. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Step Jack', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('667033f0-dbcc-40e8-9683-b72dfcd6b4da', '90 Degree Single Knee Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '59361201', '59361201-90-Degree-Single-Knee-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', '90 Degree Single Knee Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('667328a3-da9a-4aa7-9e94-00dc6079aa2e', 'Lying Side To Side Knee', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '46091201', '46091201-Lying-Side-to-Side-Knee_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Lying Side To Side Knee. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Side To Side Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('667509cd-7eb7-426b-9216-7185fc4fee7a', 'Weighted Muscle Up', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Chest","Triceps"}'::text[], 'This movement exercise emphasizes your lats for improved back development. You''ll also feel your chest, triceps working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '32861201', '32861201-Weighted-Muscle-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up in the starting position for Weighted Muscle Up. 2. Execute the movement with proper form, focusing on your lats. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'general_exercise', 'Weighted Muscle Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6680cfbd-28f0-43a5-9fa7-0e4f60e06a80', 'Hanging Side Lean (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'Build a stronger core with the Hanging Side Lean, focusing on your abs. Secondary activation of your hip flexors, grip provides additional muscle engagement. The hanging position challenges your grip while targeting the primary muscles. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '94891201', '94891201-Hanging-Side-Lean-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Hanging Side Lean. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Hanging Side Lean', 'pull_up, lat_pulldown, grip_training', FALSE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('668ea4c4-7d9d-42c6-a990-298ad45287b5', 'Single Straight Leg Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Single Straight Leg Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '28671201', '28671201-Single-Straight--Leg-Stretch-(female)_Pilates.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Move into the stretch position for Single Straight Leg Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'romanian_deadlift', 'Single Straight Leg Stretch', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('6698ece2-a75a-4db7-a8f6-fb935e13def2', 'Rope Elevated Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Rope Elevated Seated Row is a rowing exercise that builds thickness in your upper back. Your biceps, lats work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '13211201', '13211201-Cable-Rope-Elevated-Seated-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Adjust the cable machine to the correct height and attachment for Cable Rope Elevated Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Rope Elevated Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('669e89ed-30ec-4f55-95e4-bbf36c8b7687', 'Bear Walk To Rolling Rock', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Bear Walk To Rolling Rock, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '103771201', '103771201-Bear-Walk-to-Rolling-Rock-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up in the starting position for Bear Walk To Rolling Rock. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Bear Walk To Rolling Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66ac0bb4-ff9f-43c3-8a1c-bb32e3f7b248', 'Side Step Arm Pulse', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Arm Pulse is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '71901201', '71901201-Side-Step-Arm-Pulse-(male)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pulse', 'Side Step Arm Pulse', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66ba0d15-d07e-42af-98ce-e5c3409c04a5', 'Kneeling Back Rotation Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your back, the Kneeling Back Rotation Stretch helps improve mobility and prevent stiffness. The kneeling position adds a core stability challenge. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '42971201', '42971201--Kneeling-Back-Rotation-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Back Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Kneeling Back Rotation Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('66c3d675-01c5-4813-851c-c4f9e90e494e', 'Single Arm Leaning Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '24151201', '24151201-Dumbbell-Single-arm-Leaning-Lateral-Raise-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'lateral_raise', 'Single Arm Leaning Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('66dd19ac-9a3c-455d-b630-975018886a4b', 'Slight Lean Step Out', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this stepping movement that works your abs. Secondary activation of your quads provides additional muscle engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '81801201', '81801201-Slight-Lean-Step-Out-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Slight Lean Step Out. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'step_up', 'Slight Lean Step Out', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66de4e7d-e53b-4876-9934-15f1a140970e', 'Single Leg Calf Raise (Dumbbell)', 'Legs', 'Dumbbells', '{"Calves"}'::text[], '{}'::text[], 'The Dumbbell Single Leg Calf Raise isolates your calf muscles through a raising motion. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '39731201', '39731201-Dumbbell-Single-Leg-Calf-Raise-(female)-(VERSION-2)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'calf_raise', 'Single Leg Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('66e271a5-f321-47f0-a6a5-9d7507591463', 'Weighted Bag Good Morning', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Strengthen the back of your thighs with this movement exercise. Secondary activation of your glutes, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '88911201', '88911201-Weighted-Bag-Good-Morning-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up in the starting position for Weighted Bag Good Morning. 2. Execute the movement with proper form, focusing on your hamstrings. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Weighted Bag Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66e36a7c-6368-44e5-abce-e34e29508875', 'Jumping Squat Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '56741201', '56741201-Jumping-Squat-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Explode upward from the bottom, jumping as high as possible. 4. Land softly with bent knees and immediately descend into the next rep. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Jumping Squat Jack', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('66e80aa7-8571-42ce-91af-73d032ca9fea', 'Prayer Circle', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Prayer Circle, an effective movement movement for upper body strength. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '103631201', '103631201-Prayer-Circle-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Prayer Circle. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Prayer Circle', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('66f442e1-74e3-4010-8e4e-92d016430501', 'Standing Rear Kick (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. Performing this standing challenges your balance and core engagement. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '36131201', '36131201-Lever-Standing-Rear-Kick-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Standing Rear Kick. 2. Stand with feet about shoulder-width apart. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Lever Standing Rear Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('66f86d19-3f1a-4bfe-b52e-a1606d20876b', 'Seated Sky Gaze', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '81191201', '81191201-Seated-Sky-Gaze-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Sky Gaze. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Sky Gaze', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6710824f-b84a-4e93-90e1-edba79228ae7', 'Lying Frog Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Frog Crunch is a lower body crunching exercise that targets your abs. You''ll also feel your hip flexors working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '59341201', '59341201-Lying-Frog-Crunch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Frog Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Frog Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('671aa451-0063-4207-9039-341edeb3b4db', 'Single Leg Vertical Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements. A staple exercise that belongs in most training programs.', '42541201', '42541201-Single-Leg-Vertical-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Vertical Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Vertical Jump', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('671ef7b3-9a61-4f71-8e8c-b50480385d7e', 'Korean Dip', 'Chest', 'Bodyweight', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Korean Dip is a dipping exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '32881201', '32881201-Korean-Dip_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Korean Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('672acbcb-f1e1-4392-b152-78efff02b906', '90 To 90 (Alternating) - Alternating', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Perfect for including in both strength and hypertrophy programs.', '80701201', '80701201-90-to-90-(beginner)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Move into the stretch position for 90 To 90. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep the movement smooth and controlled.', 'Static / Mobility', 'Static', 'Isolation', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', '90 To 90', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6734e7ec-73aa-413a-8851-da3d3e47cfe9', 'Lying Posterior Pelvic Shift Hold - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your core for improved core stability and strength. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '77861201', '77861201-Lying-Alternate-Posterior-Pelvic-Shift-Hold-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Posterior Pelvic Shift Hold. 2. Hold the position for the prescribed time, maintaining tension. 3. Alternate between sides/arms/legs with each repetition.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Posterior Pelvic Shift Hold - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('67417913-8d32-4904-b51d-d9adc94ef66c', 'Lying Fly On Floor (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '92021201', '92021201-Dumbbell-Lying-Fly-on-Floor-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Fly On Floor. 2. Position yourself on the floor for Dumbbell Lying Fly On Floor. 3. Lie down in the appropriate position for Dumbbell Lying Fly On Floor. 4. With a slight bend in your elbows, move the weight in a wide arc. 5. Squeeze your chest muscles at the center/top of the movement. 6. Return with control, feeling the stretch at the bottom. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'chest_fly', 'Lying Fly On Floor', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('676b2cec-bc02-46c5-bc09-de6889f61593', 'Reverse Fly (Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Target your rear delts with the Band Reverse Fly, an effective shoulder flying exercise. The upper back assist throughout the movement, making this a well-rounded exercise. Bands are joint-friendly and portable, perfect for any training environment. Strong shoulders improve overhead strength and support nearly all upper body movements.', '9931201', '09931201-Band-Reverse-fly_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Secure the resistance band appropriately for Band Reverse Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'rear_delt', 'Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('67761e51-1963-4733-b5d6-f57ff81f8585', 'Roll Rectus Femoris', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Roll Rectus Femoris helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '54351201', '54351201-Roll-Rectus-Femoris-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Roll Rectus Femoris. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Rectus Femoris', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6778a544-bf60-4d2c-87fe-40fd8fa5d3a3', 'Single Arm Twisting Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, lats work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '12051201', '12051201-Cable-one-arm-twisting-seated-row_back.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Twisting Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 79, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm Twisting Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('6792fcb3-b884-424c-aa3e-7696d99662ac', 'Warrior III Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors","Core"}'::text[], 'The Warrior III Pose provides a deep stretch for your full body, ideal for recovery and mobility work. You''ll also feel your hips, shoulders, quads working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '59071201', '59071201-Warrior-III-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Move into the stretch position for Warrior III Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Warrior III Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('679b1f1b-44a7-4d29-98cd-f1c01911d4e9', 'Straight Hip Leg Curl (TRX)', 'Legs', 'TRX', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. You''ll also feel your calves working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. Lower body strength improves everything from walking to heavy compound lifts.', '11021201', '11021201-Suspender-Straight-Hip-Leg-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Straight Hip Leg Curl. 2. Curl your heels toward your glutes by bending at the knees. 3. Squeeze your hamstrings at peak contraction. 4. Extend legs back out with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_curl', 'Suspender Straight Hip Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('67c6f07e-7546-47e3-864e-1473ffceb9d0', 'Back Extension (Machine)', 'Back', 'Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension exercise engages your abs for improved core stability and strength. You''ll also feel your glutes working to support the movement. Machine exercises are great for isolating muscles and training to failure safely. Building core stability helps with everything from heavy deadlifts to daily activities.', '36071201', '36071201-Lever-Back-Extension-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Back Extension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'back_extension', 'Lever Back Extension', 'good_morning, bird_dog, superman', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('67c7fb3a-79f1-4762-9e26-ea28eda60e72', 'Arnold Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The triceps assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '23861201', '23861201-Dumbbell-Arnold-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Arnold Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'Arnold Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('67dd458f-9849-4804-b976-de8cadb63e46', 'Weighted Counterbalanced Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '57831201', '57831201-Weighted-Counterbalanced-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'balance', 'Weighted Counterbalanced Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('67df1f2a-eb24-44a4-903d-3e1eb89b19f0', 'Standing Side Circle Draw', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Standing Side Circle Draw is a movement exercise that develops back strength and muscle. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '72261201', '72261201-Standing-Side-Circle-Draw-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Side Circle Draw. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Side Circle Draw', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('67ec118d-0af2-40c3-a544-74c04395c86c', 'Sumo Romanian Deadlift (Barbell)', 'Legs', 'Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '57751201', '57751201-Barbell-Sumo-Romanian-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Sumo Romanian Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Sumo Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('67ed7ed5-2701-4488-821d-ce49980eec67', 'Front Raise (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Barbell Front Raise, an effective shoulder raising exercise. Barbells enable bilateral loading for building raw strength. Shoulder development enhances both performance and upper body aesthetics. Excellent for pre-exhausting the target muscle before compound lifts.', '24771201', '24771201-Barbell-Front-Raise-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', 'Shoulder Flexion', 'Push', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('67fae299-4f2e-4210-8488-e785bd4f9299', 'Push Up (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '45711201', '45711201-Resistance-Band-Push-Up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Secure the resistance band appropriately for Resistance Band Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('6804a64d-39bf-48a1-8b32-5faa0fc54fca', 'Front Plank On Elbow Toe Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Front Plank On Elbow Toe Tap is a lower body stabilization exercise that targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '52001201', '52001201-Front-Plank-on-Elbow-Toe-Tap-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Front Plank On Elbow Toe Tap', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('680c4ad1-b884-4603-8a31-48580185d9ed', 'Locust Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Progress gradually by increasing resistance over time. Consistency with this movement will yield noticeable results.', '62871201', '62871201-Locust-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Move into the stretch position for Locust Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Locust Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('681c7ede-861d-478a-8498-c4f78b298799', 'Bench Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength. This is a great exercise for all fitness levels with proper scaling.', '2911201', '02911201-Dumbbell-Bench-Squat_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bench Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('68479540-2277-4fae-ac65-b63f7c825227', 'Seated Behind Head Military Press (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your triceps provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '861201', '00861201-Barbell-Seated-Behind-Head-Military-Press_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Behind Head Military Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout.', 'Push', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Seated', NULL, 'Overhand', 'Wide', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Seated Behind Head Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('6858f36b-5cbc-4f6f-8ce6-3b49b29ad497', 'Standing Reverse Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your biceps work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '4291201', '04291201-Dumbbell-Standing-Reverse-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Reverse Curl. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Reverse Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('685d072d-9317-4d08-a761-c1b0dfaf4906', 'Walking', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Regular cardio training builds the aerobic base for better overall fitness. Keep your core engaged throughout the exercise.', '22581201', '22581201-Walking_Cardio-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Set up in the starting position for Walking. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('686668f0-462f-4a9f-a589-29b9c02eb1c2', 'Long Distance Running', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Long Distance Running is a cardiovascular exercise that improves endurance and heart health. Regular cardio training builds the aerobic base for better overall fitness.', '88101201', '88101201-Long-Distance-Running-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Set up in the starting position for Long Distance Running. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'running', 'Long Distance Running', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('686c83ca-8614-4b86-9036-639b7e82f13b', 'Seated Floor Diagonal Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. You''ll also feel your hip flexors working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '93431201', '93431201-Sitting-Floor-Diagonal-Knee-Raise_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Position yourself on the floor for Seated Floor Diagonal Knee Raise. 2. Sit on the floor with your legs positioned as required. 3. Raise the weight in the prescribed direction for Seated Floor Diagonal Knee Raise. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Floor Diagonal Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('687a970c-f5c0-4e0e-9cf9-999db176fb6e', 'Bent Arm Pullover (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'The Barbell Bent Arm Pullover is a pulling exercise that develops back strength and muscle. Your lats, triceps work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. A strong back improves posture, prevents injury, and balances pressing movements.', '75651201', '75651201-Barbell-Bent-Arm-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Grip a barbell with hands at the appropriate width for Barbell Bent Arm Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Bent Arm Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('687d68bf-a809-4173-a9ee-bc77e70f5ea5', 'Standing Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '4301201', '04301201-Dumbbell-Standing-Triceps-Extension_Upper-Arms-FIX.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Triceps Extension. 2. Begin in a standing position with good posture. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'Standing Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('68888ec5-5a37-4640-969c-19e7392ea2ac', 'Jumping Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '11981201', '11981201-Jumping-Pull-up_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Control the movement—avoid using momentum. Ideal for lats strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'pull_up', 'Jumping Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 60, 4, 70, 88, 95, 65),
('689069b7-c0e9-42b4-9f25-5d51dc8a2a66', 'Single Leg Deadlift (Dumbbell)', 'Back', 'Dumbbells', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Dumbbell Single Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '85001201', '85001201-Dumbbell-Single-Leg-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'deadlift', 'Single Leg Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('68926284-4eab-4504-abf2-423e5385a9d0', 'Zottman Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Zottman Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '70641201', '70641201-Dumbbell-Zottman-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Zottman Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'bicep_curl', 'Zottman Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('689765fa-9e10-4d74-a043-0e2c98713079', 'Weighted Seated Single Arm Wrist Curl', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Weighted Seated One Arm Wrist Curl strengthens your forearms and grip through a curling motion. You''ll also feel your forearms working to support the movement. The seated position helps isolate the target muscles by removing momentum. Arm strength supports grip, pulling, and pushing in compound movements.', '42331201', '42331201-Weighted-Seated-One-Arm-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', 'Curl', 'Pull', NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'wrist_curl', 'Weighted Seated Single Arm Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('68a064ed-c80d-4fc2-a81f-3b462cccac93', 'Squat To Front Lunge - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Progress gradually by increasing resistance over time.', '96321201', '96321201-Alternate-Squat-to-Front-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. This variation specifically emphasizes the quads. Variation: Alternate Squat To Front Lunge.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat To Front Lunge - Alternating', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('68a07f38-ad62-477c-bdec-f92f30388de7', 'Incline Bench Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Dumbbell Incline Bench Press is a pressing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '24411201', '24411201-Dumbbell-Incline-Bench-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'incline_press', 'Incline Bench Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('68abe9aa-42a9-4ec9-abab-af90bee5c66f', 'Hack Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '461201', '00461201-Barbell-Hack-Squat_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'hack_squat', 'Hack Squat', 'leg_press, squat, leg_extension', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('68b6c8eb-0631-46f6-9f1d-47e111b9052a', 'Standing Top Grab Front Grab', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Standing Top Grab Front Grab, an effective movement movement for upper body strength. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '64461201', '64461201-Standing-Top-Grab-Front-Grab-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Top Grab Front Grab. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'core_exercise', 'Standing Top Grab Front Grab', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('68c12c26-f78d-4a22-bbab-089cb32d426e', 'Seated Straight Leg Calf Stretch', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'The Seated Straight Leg Calf Stretch isolates your calf muscles through a stretching motion. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts.', '6931201', '06931201-Seated-Straight-Leg-Calf-Stretch-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Straight Leg Calf Stretch. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'romanian_deadlift', 'Seated Straight Leg Calf Stretch', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('68c53884-aa20-4ccb-a825-86f86632ed47', 'Single Arm Lateral Raise (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '91301201', '91301201-Resistance-Band-Single-Arm-Lateral-Raise-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Single Arm Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'lateral_raise', 'Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('68caace5-6033-41b9-bb12-98c41361c81c', 'Preacher Curl - Close Grip (EZ Bar)', 'Arms', 'EZ Bar, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. Using a barbell provides stability for progressive overload. Dedicated arm training builds both strength and muscular definition.', '70121201', '70121201-EZ-Barbell-Close-Grip-Preacher-Curl-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Close Grip Preacher Curl. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'EZ Preacher Curl - Close Grip', 'EZ Preacher Curl - Close Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('68cde08e-f2c5-4be4-9601-77dda27db617', 'Seated Row - Wide Grip (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Seated Wide Grip Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '35981201', '35981201-Cable-Seated-Wide-grip-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Wide Grip Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row - Wide Grip', 'Seated Row - Wide Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('68df5a0e-c376-48f3-8f42-75b8f7d7604e', 'Front Kick Forward Push - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'A challenging plyometric exercise, the Alternating Front Kick Forward Push builds reactive power and improves conditioning. Your quads work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '93751201', '93751201-Alternating-Front-Kick-Forward-Push-(female)_Plyom.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternating Front Kick Forward Push. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Front Kick Forward Push - Alternating', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('68ef1326-e3ef-4fb5-bce5-cb627d9ceaa7', 'Step Side Jump Over Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '101331201', '101331201-Step-Side-Jump-over-StepBox-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Step Side Jump Over Stepbox. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Step Side Jump Over Stepbox', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('68f1ea6d-add4-4973-b1c9-56e9c7f789de', 'Standing Outer To Inner Arm Throw', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your upper back with the Standing Outer To Inner Arm Throw, an effective shoulder rowing exercise. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '96201201', '96201201-Standing-Outer-to-Inner-Arm-Throw-(female)_Shoulde.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Outer To Inner Arm Throw', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('68fbfd2c-aa6b-4e7a-8c5b-95f57144a54f', 'Seated Leg Hug Cat Cow', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'This stretch specifically works on your spine, promoting flexibility and reducing muscle tightness. The core assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85621201', '85621201-Seated-Leg-Hug-Cat-Cow-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Leg Hug Cat Cow. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Leg Hug Cat Cow', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('69008552-3065-4bb6-b5fd-efb7feae77a4', 'Double Side Step Kickback Row', 'Back', 'Bodyweight', '{"Triceps"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build power and athleticism with this high-intensity rowing exercise that challenges your entire body. The hamstrings assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '93811201', '93811201-Double-Side-Step-Kickback-Rows-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'tricep_kickback', 'Double Side Step Kickback Row', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('692275f0-69ba-472a-b2b4-9d14c453c28f', 'Single Leg Squat (Stability Ball)', 'Legs', 'Stability Ball', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Leg training boosts metabolism and builds functional, real-world strength.', '70141201', '70141201-Stability-Ball-Single-Leg-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Position the stability ball as needed for Stability Ball Single Leg Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'pistol_squat', 'Stability Ball Single Leg Squat', 'squat, bench_press, deadlift', TRUE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('692387cf-4618-465f-87d7-6128a44e56ab', 'Windmill (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kettlebell Windmill is a core movement exercise that primarily targets your abs. The kettlebell''s offset center of mass increases the stability challenge. A strong core improves posture, protects your spine, and enhances all other lifts.', '45191201', '45191201-Kettlebell-Windmill-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Windmill. 2. Set up in the starting position for Kettlebell Windmill. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Windmill', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
